import { Order } from './types';
const cmp = (aDate: string, aId: string, bDate: string, bId: string): number =>
  aDate < bDate ? -1 : aDate > bDate ? 1 : aId < bId ? -1 : aId > bId ? 1 : 0;
export class OrderRepository {
  constructor(private readonly rows: Order[]) {}
  // Tenant-filtered, sorted copy; optionally only rows strictly after the (createdAt, id) pair.
  list(tenant: string, after?: { createdAt: string; id: string }): Order[] {
    return this.rows
      .filter(row => row.tenant === tenant && (!after || cmp(row.createdAt, row.id, after.createdAt, after.id) > 0))
      .sort((a, b) => cmp(a.createdAt, a.id, b.createdAt, b.id));
  }
}
